// Renders the agent's hash-chained audit log (live/state/audit.jsonl) as a human-readable,
// EU AI Act Art. 12-style record with a CCDExplorer link for every on-chain transaction it names.
// Pure rendering + one read-only chain lookup (block time and outcome of each transaction).
// The record itself is the JSONL file; this is a view of it, regenerated by tools/write-audit-doc.mjs.
import { BlockHash, TransactionHash } from '@concordium/web-sdk';
import { isTxField, txHashesIn } from './audit-anchor.mjs';
import { explorerAccount, explorerContract, explorerTx } from './net.mjs';

export const BADGE_CHECK_URL = 'https://agent-registry-mcp.concordium.com/v1/check-badge';

/** What each logged event means, in one line. Unknown events are rendered with their raw name. */
export const EVENT_MEANING = Object.freeze({
  request: 'The agent was asked to fetch a paid resource (input: intent and URL).',
  quote: 'The seller answered HTTP 402 with x402 payment requirements (amount, payee, payee badge).',
  authorized: 'The guard contract checked the payment against the on-chain policy (caps, allowlist, threshold).',
  human_approved: 'The owner approved this exact authorisation with a ZK proof from the owner account\'s identity credential (no identity attributes disclosed); the record is anchored on chain.',
  approved_without_proof: 'The owner key approved without a verifiable human proof (attack scenario).',
  approved_with_replayed_proof: 'The owner key approved with a genuine proof that belongs to a different authorisation (attack scenario).',
  cosigned: 'The co-signer re-checked everything, committed the exact transaction digest on chain and signed key 1.',
  paid: 'The x402 facilitator settled the sponsored transfer from the 2-of-2 wallet.',
  settled: 'The settlement transaction was recorded in the guard.',
  refused: 'The payment was refused; nothing was paid.',
});

const TX_LABELS = Object.freeze({
  authorized: { txHash: 'authorize' },
  human_approved: { requestTx: 'verification request anchor', anchorTx: 'approval record anchor', approveTx: 'approve(id, proof)' },
  approved_without_proof: { approveTx: 'approve (no valid proof)' },
  approved_with_replayed_proof: { approveTx: 'approve (replayed proof)' },
  cosigned: { commitTx: 'commitPayment' },
  paid: { txHash: 'x402 settlement' },
  settled: { txHash: 'x402 settlement', recordTx: 'recordSettlement' },
  refused: { cancelTx: 'cancel' },
});

const HEX64 = /^[0-9a-f]{64}$/i;
const short = (h) => `${String(h).slice(0, 10)}…`;
/**
 * Escape untrusted text for a Markdown table cell: every character that could open a link, image,
 * code span, emphasis or HTML is backslash-escaped (or entity-encoded), and newlines are flattened.
 */
export const cell = (v) => String(v ?? '')
  .replace(/\r?\n|\r/g, ' ')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/[\\`*_{}\[\]()#+!|~]/g, (c) => `\\${c}`);
/** A code span for values made only of safe characters (reason codes, URLs); anything else is escaped text. */
export const code = (v) => (/^[A-Za-z0-9_:.\/?=&%,@\u2026-]+$/.test(String(v ?? '')) ? `\`${String(v)}\`` : cell(v));
const BASE58 = /^[1-9A-HJ-NP-Za-km-z]+$/;
const isAccount = (a) => BASE58.test(String(a ?? '')) && String(a).length === 50;
export const ccd = (micro) => {
  if (!/^\d+$/.test(String(micro ?? ''))) return cell(micro);
  const s = String(micro).padStart(7, '0');
  const frac = s.slice(-6).replace(/0+$/, '');
  return `${s.slice(0, -6).replace(/^0+(?=\d)/, '')}${frac ? `.${frac}` : ''} CCD`;
};
const linkTx = (h, label = short(h)) => (HEX64.test(String(h)) ? `[${label}](${explorerTx(String(h).toLowerCase())})` : `${code(h)} (not a transaction hash)`);
const linkAccount = (a) => (isAccount(a) ? `[${short(a)}](${explorerAccount(a)})` : `${cell(a)} (not an account address)`);
const linkBadge = (b) => (BASE58.test(String(b ?? '')) ? `[${b}](${BADGE_CHECK_URL}/${b})` : cell(b));

/** Every transaction one entry names, with a label: [{field, label, hash}]. */
export function entryTxs(entry) {
  const labels = TX_LABELS[entry?.event] ?? {};
  return Object.entries(entry?.data ?? {})
    .filter(([k, v]) => isTxField(k) && v !== null && v !== undefined && v !== '')
    .map(([k, v]) => ({ field: k, label: labels[k] ?? k, hash: String(v).toLowerCase() }));
}

/** Drop repeats of the same transaction (the settlement is named by both `paid` and `settled`). */
export const uniqueTxs = (txs) => txs.filter((t, i) => txs.findIndex((u) => u.hash === t.hash) === i);

/** Plain-language details of one entry (no transaction links; those are rendered separately). */
export function entryDetails(entry) {
  const d = entry?.data ?? {};
  const parts = [];
  if (d.authId !== undefined && d.authId !== null) parts.push(`authorisation #${cell(d.authId)}`);
  if (d.intent) parts.push(`intent "${cell(d.intent)}"`);
  if (d.url) parts.push(`resource ${code(d.url)}`);
  if (d.amount !== undefined) parts.push(ccd(d.amount));
  if (d.payTo) parts.push(`payee ${linkAccount(d.payTo)}`);
  if (d.badge) parts.push(`payee badge ${linkBadge(d.badge)}`);
  if (d.status) parts.push(`guard status **${cell(d.status)}**`);
  if (d.stage) parts.push(`refused by ${cell(d.stage)}`);
  if (d.reason) parts.push(`reason ${code(d.reason)}`);
  if (d.released !== undefined) parts.push(d.released ? 'daily budget released' : 'budget not released');
  if (d.anchorHash) parts.push(`approval record hash ${code(short(d.anchorHash))}`);
  return parts.join('; ');
}

/**
 * Split the log into uses (one per purchase). Entries carrying a `request` id (logged by
 * LiveAgent.buy since the id was introduced) join the use that id started, so concurrent purchases
 * stay apart. An entry naming an authorisation joins the use in which that authorisation first
 * appeared, so a payment approved or settled later (a resumed pending payment) stays with its task.
 * An entry naming an authorisation the log never saw authorised gets a row of its own. Older entries
 * without either id fall back to the latest `request`; entries before any request form a use of their own.
 */
export function groupUses(entries) {
  const uses = [];
  const byRequest = new Map();
  const byAuth = new Map();
  const keyOf = (v) => (v === undefined || v === null || v === '' ? null : String(v));
  for (const e of entries) {
    const rid = keyOf(e?.data?.request);
    const aid = keyOf(e?.data?.authId);
    let use;
    if (e.event === 'request' || uses.length === 0) {
      use = { entries: [] };
      uses.push(use);
      if (rid !== null && e.event === 'request') byRequest.set(rid, use);
    }
    if (aid !== null && byAuth.has(aid)) use = byAuth.get(aid);
    else if (rid !== null && byRequest.has(rid)) use = byRequest.get(rid);
    else if (!use && aid !== null && e.event !== 'authorized') {
      // An authorisation this log never saw authorised (e.g. a resume after a restart): its own row, never another task's.
      use = { entries: [] };
      uses.push(use);
    }
    use ??= uses.at(-1);
    if (aid !== null && !byAuth.has(aid)) byAuth.set(aid, use);
    use.entries.push(e);
  }
  return uses;
}

/** State after each lifecycle event; the use's outcome is the state after its last lifecycle event. */
const STATE_AFTER = Object.freeze({
  authorized: (e) => `authorised (${cell(e.data?.status ?? '?')}), not yet paid`,
  human_approved: () => 'approved by a verified human, not yet co-signed',
  approved_without_proof: () => 'approved by the owner key without a valid proof, not yet co-signed',
  approved_with_replayed_proof: () => 'approved by the owner key with a replayed proof, not yet co-signed',
  cosigned: () => 'co-signed, not yet settled',
  paid: () => 'paid, not yet recorded in the guard',
  settlement_unknown: () => 'settlement outcome unknown',
  settlement_record_failed: () => 'paid, but recording the settlement in the guard failed',
  settled: () => 'paid and recorded',
  refused: (e) => `refused (${cell(e.data?.stage ?? '?')}: ${code(e.data?.reason ?? '?')})`,
});

/** One-line outcome of a use, from the last lifecycle event it logged. */
export function useOutcome(use) {
  const last = use.entries.findLast((e) => STATE_AFTER[e.event]);
  if (last) return STATE_AFTER[last.event](last);
  return use.entries.length ? `ended after ${code(use.entries.at(-1).event)}` : 'empty';
}

/** Who/what approved a use, in words. A refusal is claimed only once a refusal is logged. */
export function useApproval(use, thresholdMicro) {
  const has = (n) => use.entries.some((e) => e.event === n);
  const cosignerRefused = use.entries.some((e) => e.event === 'refused' && e.data?.stage === 'cosigner');
  const then = cosignerRefused ? ': refused by the co-signer' : (has('cosigned') ? ', co-signed' : ' (co-signer not yet asked)');
  if (has('human_approved')) return 'verified human (ZK proof, anchored)';
  if (has('approved_without_proof')) return `owner key without a valid proof${then}`;
  if (has('approved_with_replayed_proof')) return `owner key with a replayed proof${then}`;
  const auth = use.entries.find((e) => e.event === 'authorized');
  if (auth?.data?.status === 'Approved') {
    const amt = use.entries.find((e) => e.data?.amount !== undefined)?.data?.amount;
    return thresholdMicro !== undefined && amt !== undefined && /^\d+$/.test(String(amt)) && BigInt(amt) <= BigInt(thresholdMicro)
      ? `policy (at or below the ${ccd(thresholdMicro)} threshold)` : 'policy';
  }
  if (auth?.data?.status === 'Pending') return 'awaiting approval';
  return '—';
}

/**
 * Read-only: block time, height and outcome of each transaction. A hash that is not found or not
 * finalized is reported as such; other read errors propagate (the report never guesses).
 * @returns {Promise<Map<string, {finalized: boolean, blockHeight?: bigint, blockTime?: string, outcome?: string}>>}
 */
export async function resolveTxInfo(grpc, hashes) {
  const out = new Map();
  for (const h of new Set(hashes.map((x) => String(x).toLowerCase()))) {
    if (!HEX64.test(h)) { out.set(h, { finalized: false, invalid: true }); continue; }
    let st;
    try { st = await grpc.getBlockItemStatus(TransactionHash.fromHexString(h)); } catch (e) {
      if (/not ?found/i.test(String(e?.message ?? e))) { out.set(h, { finalized: false }); continue; }
      throw e;
    }
    const bh = st?.status === 'finalized' ? st?.outcome?.blockHash : null;
    if (!bh) { out.set(h, { finalized: false, status: st?.status ?? 'unknown' }); continue; }
    const info = await grpc.getBlockInfo(typeof bh === 'string' ? BlockHash.fromHexString(bh) : bh);
    const s = st.outcome.summary ?? {};
    const outcome = s.transactionType === 'failed' ? `rejected${s.rejectReason?.tag ? ` (${s.rejectReason.tag})` : ''}` : 'success';
    const t = info.blockSlotTime instanceof Date ? info.blockSlotTime.getTime() : Number(info.blockSlotTime);
    out.set(h, { finalized: true, blockHeight: BigInt(info.blockHeight), blockTime: new Date(t).toISOString(), outcome });
  }
  return out;
}

const txCell = (txs, info) => txs.map((t) => {
  const i = info?.get(t.hash);
  const when = i?.finalized ? ` — ${i.blockTime}, ${i.outcome}` : (info ? ' — not finalized / not found' : '');
  return `${cell(t.label)}: ${linkTx(t.hash)}${when}`;
}).join('<br>');

function useTimes(use, info) {
  const txs = uniqueTxs(use.entries.flatMap(entryTxs));
  const times = txs.map((t) => info?.get(t.hash)).filter((i) => i?.finalized).map((i) => i.blockTime).sort();
  if (times.length) return `${times[0] === times.at(-1) ? times[0] : `${times[0]} → ${times.at(-1)}`}${times.length < txs.length ? ' (some transactions not finalized / not found)' : ''}`;
  const first = cell(use.entries[0]?.at ?? '?');
  const last = cell(use.entries.at(-1)?.at ?? '?');
  const clock = `agent clock ${first === last ? first : `${first} → ${last}`}`;
  if (!txs.length) return `${clock} (no transaction)`;
  return info ? `${clock} (transactions not finalized / not found)` : `${clock} (block times not read: offline)`;
}

/**
 * The Markdown report.
 * @param {object} p
 * @param {object[]} p.entries          audit log entries (verified or not; p.chain says which)
 * @param {{ok: boolean, brokenAt?: number}} p.chain   result of AuditLog.verify
 * @param {object} p.state              live/state/testnet.json
 * @param {object} p.run                live/state/run.json
 * @param {Map}    [p.txInfo]           from resolveTxInfo; omitted = offline (no block times)
 * @param {{ok: boolean, reasons: string[], onChainAuthCount?: number}} [p.anchorCheck]  checkAuditAnchor result
 * @param {string} [p.readAt]           when the chain was read (ISO UTC)
 */
export function renderAuditReport({ entries, chain, state, run, txInfo, anchorCheck, readAt }) {
  const g = state.guard;
  const guardLink = `[<${g.address.index},${g.address.subindex}>](${explorerContract(g.address.index, g.address.subindex)})`;
  const thr = g.policy?.approval_threshold;
  const anchors = (run.steps ?? []).filter((s) => s.step === 'anchor');
  const anchor = anchors.at(-1);
  const out = [];
  out.push('# TrustRail audit record (EU AI Act Art. 12-style)', '',
    `The buyer agent's own log, \`live/state/audit.jsonl\`: ${entries.length} entries, each holding the SHA-256 of the one before it,`,
    `whose head is meant to be anchored on Concordium **testnet** in the guard contract ${guardLink} (see Integrity). Every transaction an entry names links to CCDExplorer.`,
    'Generated by `live/tools/write-audit-doc.mjs` (`cd live && npm run audit:doc`, no keys). The generator reads the chain and writes local Markdown only; it sends no transactions and publishes nothing. This file is a view; the JSONL file is the record.', '',
    '> Scope: this demo agent is not a high-risk AI system under the AI Act and this is not a conformity assessment.',
    '> It shows how an agent that moves money can keep Art. 12-style logs that a deployer or an auditor can check against the chain instead of taking the operator\'s word (limits: README, "Trust assumptions and known limitations").', '');

  out.push('## Integrity', '');
  out.push(`- Hash chain: ${chain.ok ? `**intact** (${entries.length} entries, genesis → head ${code(short(entries.at(-1)?.hash ?? ''))})` : `**BROKEN at entry ${cell(chain.brokenAt)}**: the entries from there on cannot be trusted, and no anchor can vouch for them`}.`);
  if (anchor) {
    const i = txInfo?.get(String(anchor.txHash).toLowerCase());
    const covers = anchor.head === entries.at(-1)?.hash && Number(anchor.count) === entries.length;
    const coverage = !chain.ok ? 'It cannot vouch for a broken chain.'
      : covers ? 'Its head and count equal this log\'s last entry and length.' : '**It does not cover the whole log** (entries were added after it, or the log was changed).';
    out.push(`- Latest anchor recorded in \`live/state/run.json\`: head ${code(short(anchor.head))} of ${cell(anchor.count)} entries, \`anchorAudit\` ${linkTx(anchor.txHash)}${i?.finalized ? ` (block ${i.blockHeight}, ${i.blockTime}, ${i.outcome})` : ''}. ${coverage}`);
    for (const a of anchors.slice(0, -1)) out.push(`- Earlier anchor: ${cell(a.count)} entries, ${linkTx(a.txHash)}.`);
  } else out.push('- **No anchor** is recorded in `live/state/run.json`: nothing on chain vouches for this log.');
  if (anchorCheck) {
    const pass = anchorCheck.ok && chain.ok;
    const why = [...(chain.ok ? [] : ['the hash chain is broken']), ...anchorCheck.reasons].map(cell).join('; ');
    out.push(`- Chain check at ${cell(readAt ?? '?')}: ${pass ? `**PASS**. The \`AuditAnchored\` event matches this log and postdates every transaction it names, and the log records the current lifecycle of all ${cell(anchorCheck.onChainAuthCount)} authorisations the guard holds` : `**FAIL**: ${why || 'unknown'}`}.`);
  } else out.push('- Chain check: **not run** (generated with `--offline`). The anchor above is unverified here; run `npm run verify` or `npm run audit:doc`.');
  out.push('- What an anchor does and does not prove: see "Trust assumptions and known limitations" in the README.', '');

  out.push('## Uses of the agent', '',
    'One row per task the agent was given. Times are Concordium block times (UTC) of the transactions the use produced, the authoritative clock.', '',
    '| # | Period of use (block time, UTC) | Input | Amount → payee | Approved by | Outcome | On chain |', '| --- | --- | --- | --- | --- | --- | --- |');
  groupUses(entries).forEach((u, n) => {
    const req = u.entries.find((e) => e.event === 'request')?.data ?? {};
    const quote = u.entries.find((e) => e.event === 'quote')?.data ?? {};
    const amt = quote.amount !== undefined ? `${ccd(quote.amount)} → ${quote.payTo ? linkAccount(quote.payTo) : '?'}` : '—';
    const txs = uniqueTxs(u.entries.flatMap(entryTxs));
    out.push(`| ${n + 1} | ${useTimes(u, txInfo)} | ${req.intent ? `"${cell(req.intent)}"` : '—'}${req.url ? ` (${code(req.url)})` : ''} | ${amt} | ${useApproval(u, thr)} | ${useOutcome(u)} | ${txs.length ? txs.map((t) => `${cell(t.label)} ${linkTx(t.hash)}`).join('<br>') : (u.entries.some((e) => e.event === 'refused') ? 'none (refused before any transaction)' : 'none recorded')} |`);
  });
  out.push('');

  const logged = new Set(txHashesIn(entries.map((e) => e.data)));
  const extra = (run.steps ?? []).flatMap((s) => Object.entries(s).filter(([k, v]) => isTxField(k) && v && !logged.has(String(v).toLowerCase())).map(([k, v]) => ({ step: s.step, field: k, hash: String(v).toLowerCase() })));
  if (extra.length) {
    out.push('## On-chain evidence outside the agent\'s own log', '',
      'Transactions from the demo run (`live/state/run.json`) that the agent did not log itself: the audit anchors, and the hijacked',
      'agent\'s direct `authorize` call that the guard rejected. They are on chain in the guard\'s history either way.', '',
      '| Scenario | Transaction | Block time (UTC), outcome |', '| --- | --- | --- |');
    const seen = new Set();
    for (const x of extra) {
      if (seen.has(x.hash)) continue;
      seen.add(x.hash);
      const i = txInfo?.get(x.hash);
      out.push(`| ${cell(x.step)} (${cell(x.field)}) | ${linkTx(x.hash)} | ${i?.finalized ? `${i.blockTime}, ${i.outcome}` : (txInfo ? 'not finalized / not found' : '—')} |`);
    }
    out.push('');
  }

  out.push('## How this maps to Art. 12', '',
    '| Art. 12 asks for | Where TrustRail records it |', '| --- | --- |',
    '| 12(1): events recorded **automatically** over the system\'s lifetime | The agent code appends every step itself (`agent/src/audit/log.mjs`); nobody types entries. Each entry hashes the previous one and the head is anchored with `anchorAudit`, so a deleted or edited entry shows. |',
    '| 12(2)(a): situations that may make the system a risk, or a substantial change | Every refusal with a stable reason code (local preflight `PerTxCap`, `payee_not_bound_to_badge`, co-signer `human_approval_record_unavailable` / `approval_wrong_resource`), on-chain rejections, and every human approval. The policy itself lives in the guard; `updatePolicy` / `setPaused` emit guard events. |',
    '| 12(2)(b): data for post-market monitoring (Art. 72) | The JSONL log (machine-readable) and the "Uses" table above; on-chain guard events for every authorisation. |',
    '| 12(2)(c): monitoring of operation by the deployer (Art. 26(5)) | This report plus `npm run verify`: anyone can recheck badges, caps, approvals, settlements and the anchor without keys. |',
    '| *Art. 12(3) applies only to the remote biometric identification systems of Annex III point 1(a). Its four items are listed here with their actual meaning; what TrustRail records is an analogue, not that requirement.* | |',
    '| 12(3)(a): the period of each use (start and end date and time) | Analogue: block times (UTC) of the transactions each use produced (column 2 of "Uses"). |',
    '| 12(3)(b): the reference database the input data was checked against | Analogue: what each payment was checked against — the guard\'s on-chain policy (caps, allowlist, threshold) and the CIS-8004 Agent Registry badges of payee and agent. |',
    '| 12(3)(c): the input data for which the search led to a match | Analogue: the inputs each decision was made on — the task (intent, URL) and the x402 quote (amount, payee, badge). |',
    '| 12(3)(d): identification of the natural persons who verified the results (Art. 14(5)) | Analogue: the approver of each large payment is identified by the owner account, pseudonymously. In this demo the identity is a Concordium **testnet** test identity with dummy attributes, and the proof (age ≥ 18 from that account\'s credential) is produced by a script holding the owner\'s testnet seed. The proof discloses no identity attributes; on mainnet the real person behind the account can be identified only through Concordium\'s identity disclosure process (identity provider and Privacy Guardians, on a lawful request). |',
    '| Art. 19(1) / 26(6): keep the automatically generated logs for at least six months | Anchors and guard events stay on chain. The JSONL file is the operator\'s to keep; a truncated or rewritten copy fails `npm run verify` (within the limits in the README). |', '',
    'Data protection: the proofs reveal no identity attributes, but the log keeps task inputs (intents, URLs) and account addresses verbatim. Whoever runs the agent should treat those fields as possibly personal data.', '');

  out.push('## Every entry', '',
    '`logged at` is the agent host\'s clock as written into the entry; the block time of each transaction is authoritative.', '',
    '| seq | logged at | event | what it means | details | on chain (block time UTC, outcome) |', '| --- | --- | --- | --- | --- | --- |');
  for (const e of entries) {
    const txs = entryTxs(e);
    out.push(`| ${cell(e.seq)} | ${cell(e.at)} | ${code(e.event)} | ${cell(EVENT_MEANING[e.event] ?? 'event not in the standard vocabulary')} | ${entryDetails(e) || '—'} | ${txs.length ? txCell(txs, txInfo) : '—'} |`);
  }
  out.push('', `Entry hashes: first ${code(short(entries[0]?.hash ?? ''))}, last ${code(short(entries.at(-1)?.hash ?? ''))}. Full hashes are in the JSONL file.`, '');
  return out.join('\n');
}
